export const getCardsInSet = (code: string) => {
  return ALL_CARDS.filter((card) => card.code.startsWith(code));
};

export const getCardsInExpansion = (name: string) => {
  const packs = getExpansionPacks(name);
  return packs.map((pack) => getCardsInSet(pack.code)).flat();
};

export const findCardByCode = (code: string) => {
  const card = ALL_CARDS.find((card) => card.code === code);
  if (!card) {
    throw Error(`could not find card by code: ${code}`);
  }

  return card;
};

export const getPackPointsCost = (code: string) => {
  const card = findCardByCode(code);
  switch (card.rarity) {
    case "Common":
      return 15 * 1;
    case "Rare":
      return 15 * 2;
    case "Super Rare":
      return 15 * 5;
    case "Ultra Rare":
      return 15 * 12;
    case "Secret Rare":
      return 15 * 24;
    case "Short Print":
      return 15 * 30;
    case "Super Short Print":
      return 15 * 60;
    default:
      return Infinity;
  }
};

export const getDisenchantValue = (card: CardMetadata) => {
  switch (card.rarity) {
    case "Common":
      return Math.round(0.032 * 500 * (1 / 8));
    case "Rare":
      return Math.round(0.034 * 500 * 1);
    case "Super Rare":
      return Math.round(0.0448 * 500 * 5);
    case "Ultra Rare":
      return Math.round(0.053 * 500 * 12);
    case "Secret Rare":
      return Math.round(0.06625 * 500 * 24);
    case "Short Print":
      return Math.round(0.06893 * 500 * 30);
    case "Super Short Print":
      return Math.round(0.07157 * 500 * 60);
    default:
      throw Error(`unknown rarity: ${card.rarity}`);
  }
};

export const getThumbnailUrl = (card: CardMetadata) => {
  console.debug(card);
  const url = new URL(card.imageUrl);
  const [, , dir1, dir2, filename] = url.pathname.split("/");
  const { thumbnailSize = 180 } = card;
  url.pathname = `//thumb/${dir1}/${dir2}/${filename}/${thumbnailSize}px-${filename}`;
  return url.href;
};

export const getCostOfRemainingCards = (
  cards: CardMetadata[],
  binder: BinderModel | null,
) => {
  return cards.reduce((accumulator, card) => {
    const quantity = binder?.[card.code] ?? 0;
    const quantityMissing = quantity > 3 ? 0 : 3 - quantity;
    return accumulator + getPackPointsCost(card.code) * quantityMissing;
  }, 0);
};
